export const EMBEDDED_HTML = "<!doctype html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <meta name=\"description\" content=\"Restream Panel — RTMP restream server configuration dashboard\" />\r\n    <title>Restream Panel</title>\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\r\n    <link\r\n      href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600&display=swap\"\r\n      rel=\"stylesheet\"\r\n    />\r\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\r\n  </head>\r\n  <body>\r\n    <div id=\"app\"></div>\r\n    <script type=\"module\" src=\"/main.js\"></script>\r\n  </body>\r\n</html>\r\n";
export const EMBEDDED_CSS = "/* Public Sans (Body) */\r\n@import url(\"https://fonts.googleapis.com/css2?family=Public+Sans:wght@300;400;500;600&display=swap\");\r\n/* Outfit (Headings) */\r\n@import url(\"https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&display=swap\");\r\n/* JetBrains Mono (Code) */\r\n@import url(\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500&display=swap\");\r\n\r\n:root {\r\n  --bg-void: #09090b;\r\n  --bg-panel: #121214;\r\n  --bg-card: #18181b;\r\n\r\n  --accent: #00ff88;\r\n  --accent-glow: rgba(0, 255, 136, 0.2);\r\n  --accent-text: #00331b;\r\n\r\n  --text-main: #f4f4f5;\r\n  --text-muted: #a1a1aa;\r\n\r\n  --danger: #ef4444;\r\n  --warning: #f59e0b;\r\n  --success: #00ff88;\r\n\r\n  --border: #27272a;\r\n\r\n  --font-sans: \"Public Sans\", system-ui, -apple-system, sans-serif;\r\n  --font-display: \"Outfit\", system-ui, sans-serif;\r\n  --font-mono: \"JetBrains Mono\", monospace;\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\nbody {\r\n  margin: 0;\r\n  font-family: var(--font-sans);\r\n  background-color: var(--bg-void);\r\n  color: var(--text-main);\r\n  min-height: 100vh;\r\n  /* Noise texture */\r\n  background-image: url(\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.05'/%3E%3C/svg%3E\");\r\n}\r\n\r\n/* Animations */\r\n@keyframes fadeIn {\r\n  from {\r\n    opacity: 0;\r\n    transform: translateY(10px);\r\n  }\r\n  to {\r\n    opacity: 1;\r\n    transform: translateY(0);\r\n  }\r\n}\r\n\r\n@keyframes pulse {\r\n  0% {\r\n    box-shadow: 0 0 0 0 var(--accent-glow);\r\n  }\r\n  70% {\r\n    box-shadow: 0 0 0 6px rgba(0, 255, 136, 0);\r\n  }\r\n  100% {\r\n    box-shadow: 0 0 0 0 rgba(0, 255, 136, 0);\r\n  }\r\n}\r\n\r\n@keyframes scanline {\r\n  0% {\r\n    transform: translateX(-100%);\r\n  }\r\n  100% {\r\n    transform: translateX(100%);\r\n  }\r\n}\r\n\r\n/* Layout */\r\n.header {\r\n  border-bottom: 1px solid var(--border);\r\n  background: rgba(9, 9, 11, 0.8);\r\n  backdrop-filter: blur(12px);\r\n  position: sticky;\r\n  top: 0;\r\n  z-index: 100;\r\n  overflow: hidden;\r\n}\r\n\r\n.header::after {\r\n  content: \"\";\r\n  position: absolute;\r\n  bottom: 0;\r\n  left: 0;\r\n  width: 100%;\r\n  height: 1px;\r\n  background: linear-gradient(90deg, transparent, var(--accent), transparent);\r\n  animation: scanline 3s linear infinite;\r\n  opacity: 0.5;\r\n}\r\n\r\n.container {\r\n  max-width: 1200px;\r\n  margin: 0 auto;\r\n  padding: 0 1.5rem;\r\n}\r\n\r\n.header-content {\r\n  height: 80px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n\r\n.header-brand {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1rem;\r\n}\r\n\r\n.header-logo {\r\n  color: var(--accent);\r\n  width: 32px;\r\n  height: 32px;\r\n}\r\n\r\nh1 {\r\n  font-family: var(--font-display);\r\n  font-weight: 700;\r\n  margin: 0;\r\n  font-size: 1.5rem;\r\n  letter-spacing: -0.02em;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.header-meta {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.header-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1.5rem;\r\n}\r\n\r\n.status-badge {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n  padding: 0.375rem 0.75rem;\r\n  background: var(--bg-panel);\r\n  border: 1px solid var(--border);\r\n  border-radius: 4px;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.status-badge.running {\r\n  border-color: rgba(0, 255, 136, 0.3);\r\n  color: var(--accent);\r\n}\r\n\r\n.status-dot {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 50%;\r\n  background: var(--text-muted);\r\n}\r\n\r\n.status-badge.running .status-dot {\r\n  background: var(--accent);\r\n  animation: pulse 2s infinite;\r\n}\r\n\r\n/* Version badge */\r\n.version-badge {\r\n  padding: 0.375rem 0.75rem;\r\n  background: var(--bg-panel);\r\n  border: 1px solid var(--border);\r\n  border-radius: 4px;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  letter-spacing: 0.05em;\r\n  color: var(--text-muted);\r\n  text-transform: lowercase;\r\n}\r\n\r\n/* Toolbar */\r\n.toolbar {\r\n  margin: 2rem 0;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n}\r\n\r\n.toolbar-info {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.05em;\r\n}\r\n\r\n/* Application Cards */\r\n.card {\r\n  background: var(--bg-card);\r\n  border: 1px solid var(--border);\r\n  border-radius: 8px;\r\n  padding: 1.5rem;\r\n  margin-bottom: 1rem;\r\n  position: relative;\r\n  overflow: hidden;\r\n  transition: all 0.2s ease;\r\n  animation: fadeIn 0.4s ease backwards;\r\n}\r\n\r\n.card:hover {\r\n  border-color: var(--text-muted);\r\n  transform: translateY(-2px);\r\n}\r\n\r\n/* Accent stripe */\r\n.card::before {\r\n  content: \"\";\r\n  position: absolute;\r\n  left: 0;\r\n  top: 0;\r\n  bottom: 0;\r\n  width: 4px;\r\n}\r\n\r\n.card-custom::before {\r\n  background: var(--accent);\r\n}\r\n.card-protected::before {\r\n  background: var(--border);\r\n}\r\n\r\n.card-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-start;\r\n  margin-bottom: 1.5rem;\r\n  padding-left: 1rem; /* Space for stripe */\r\n}\r\n\r\n.card-title {\r\n  font-family: var(--font-display);\r\n  font-size: 1.25rem;\r\n  font-weight: 600;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.75rem;\r\n}\r\n\r\n.card-subtitle {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n  margin-top: 0.25rem;\r\n}\r\n\r\n.badge {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.625rem;\r\n  padding: 0.125rem 0.375rem;\r\n  border-radius: 2px;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.05em;\r\n}\r\n\r\n.badge-custom {\r\n  background: rgba(0, 255, 136, 0.1);\r\n  color: var(--accent);\r\n  border: 1px solid rgba(0, 255, 136, 0.2);\r\n}\r\n\r\n.badge-protected {\r\n  background: var(--bg-panel);\r\n  color: var(--text-muted);\r\n  border: 1px solid var(--border);\r\n}\r\n\r\n.card-actions {\r\n  display: flex;\r\n  gap: 0.5rem;\r\n}\r\n\r\n/* RTMP Link */\r\n.rtmp-link {\r\n  background: var(--bg-void);\r\n  border: 1px solid var(--border);\r\n  padding: 0.75rem;\r\n  border-radius: 4px;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.8125rem;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1rem;\r\n  margin-bottom: 1.5rem;\r\n  margin-left: 1rem;\r\n}\r\n\r\n.rtmp-link-label {\r\n  color: var(--text-muted);\r\n  font-size: 0.625rem;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.1em;\r\n  user-select: none;\r\n}\r\n\r\n.rtmp-link-url {\r\n  flex: 1;\r\n  color: var(--text-main);\r\n}\r\n\r\n.rtmp-link-copy {\r\n  margin: -0.25rem 0;\r\n}\r\n\r\n/* Push Targets */\r\n.push-targets {\r\n  display: grid;\r\n  gap: 0.5rem;\r\n  margin-left: 1rem;\r\n}\r\n\r\n.push-target-item {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  padding: 0.75rem;\r\n  background: var(--bg-panel);\r\n  border-radius: 4px;\r\n  border: 1px solid transparent;\r\n}\r\n\r\n.push-target-item:hover {\r\n  border-color: var(--border);\r\n}\r\n\r\n.push-target-server {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.75rem;\r\n  font-weight: 500;\r\n}\r\n\r\n.push-target-server-icon {\r\n  font-size: 0.875rem;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.push-target-key {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n  background: var(--bg-void);\r\n  padding: 0.125rem 0.375rem;\r\n  border-radius: 2px;\r\n}\r\n\r\n.push-target-key.dynamic {\r\n  color: var(--accent);\r\n  background: rgba(0, 255, 136, 0.1);\r\n}\r\n\r\n/* Components */\r\n.btn {\r\n  border: none;\r\n  border-radius: 2px;\r\n  padding: 0.5rem 1rem;\r\n  font-family: var(--font-display);\r\n  font-weight: 600;\r\n  font-size: 0.875rem;\r\n  cursor: pointer;\r\n  transition: all 0.2s;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.05em;\r\n}\r\n\r\n.btn-small {\r\n  padding: 0.25rem 0.75rem;\r\n  font-size: 0.75rem;\r\n}\r\n\r\n.btn-primary {\r\n  background: var(--accent);\r\n  color: var(--accent-text);\r\n  box-shadow: 0 0 15px rgba(0, 255, 136, 0.3);\r\n}\r\n\r\n.btn-primary:hover {\r\n  background: #33ff99;\r\n  box-shadow: 0 0 20px rgba(0, 255, 136, 0.5);\r\n}\r\n\r\n.btn-secondary {\r\n  background: var(--bg-panel);\r\n  color: var(--text-main);\r\n  border: 1px solid var(--border);\r\n}\r\n\r\n.btn-secondary:hover {\r\n  border-color: var(--text-muted);\r\n}\r\n\r\n.btn-danger {\r\n  background: rgba(239, 68, 68, 0.1);\r\n  color: var(--danger);\r\n  border: 1px solid rgba(239, 68, 68, 0.2);\r\n}\r\n\r\n.btn-danger:hover {\r\n  background: rgba(239, 68, 68, 0.2);\r\n  border-color: var(--danger);\r\n}\r\n\r\n.btn-ghost {\r\n  background: transparent;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.btn-ghost:hover {\r\n  color: var(--text-main);\r\n  background: rgba(255, 255, 255, 0.05);\r\n}\r\n\r\n.btn-ghost.copied {\r\n  color: var(--accent);\r\n}\r\n\r\n/* Modal */\r\n.modal-overlay {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  right: 0;\r\n  bottom: 0;\r\n  background: rgba(0, 0, 0, 0.7);\r\n  backdrop-filter: blur(4px);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  z-index: 1000;\r\n  animation: fadeIn 0.2s;\r\n}\r\n\r\n.modal {\r\n  background: var(--bg-card);\r\n  border: 1px solid var(--border);\r\n  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);\r\n  width: 100%;\r\n  max-width: 500px;\r\n  border-radius: 8px;\r\n  overflow: hidden;\r\n  transform-origin: center;\r\n  animation: fadeIn 0.2s;\r\n}\r\n\r\n.modal-header {\r\n  padding: 1.5rem;\r\n  border-bottom: 1px solid var(--border);\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n}\r\n\r\n.modal-title {\r\n  font-family: var(--font-display);\r\n  font-size: 1.125rem;\r\n  font-weight: 600;\r\n  margin: 0;\r\n}\r\n\r\n.modal-close {\r\n  background: none;\r\n  border: none;\r\n  color: var(--text-muted);\r\n  font-size: 1.5rem;\r\n  cursor: pointer;\r\n  line-height: 1;\r\n}\r\n\r\n.modal-footer {\r\n  padding: 1.5rem;\r\n  border-top: 1px solid var(--border);\r\n  display: flex;\r\n  justify-content: flex-end;\r\n  gap: 1rem;\r\n  background: var(--bg-panel);\r\n}\r\n\r\n/* Form */\r\n.form-group {\r\n  padding: 1.5rem;\r\n}\r\n\r\n.form-label {\r\n  display: block;\r\n  font-family: var(--font-display);\r\n  font-weight: 500;\r\n  font-size: 0.875rem;\r\n  margin-bottom: 0.5rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.form-input {\r\n  width: 100%;\r\n  background: var(--bg-void);\r\n  border: 1px solid var(--border);\r\n  padding: 0.75rem;\r\n  color: var(--text-main);\r\n  font-family: var(--font-mono);\r\n  font-size: 0.875rem;\r\n  border-radius: 4px;\r\n}\r\n\r\n.form-input:focus {\r\n  outline: none;\r\n  border-color: var(--accent);\r\n  box-shadow: 0 0 0 1px var(--accent-glow);\r\n}\r\n\r\n.form-input.valid {\r\n  border-color: var(--success);\r\n}\r\n.form-input.invalid {\r\n  border-color: var(--danger);\r\n}\r\n\r\n/* Server Selector */\r\n.server-selector {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0.5rem;\r\n}\r\n\r\n.server-option {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1rem;\r\n  padding: 0.75rem;\r\n  background: var(--bg-void);\r\n  border: 1px solid var(--border);\r\n  border-radius: 4px;\r\n  cursor: pointer;\r\n  transition: all 0.2s;\r\n}\r\n\r\n.server-option:hover {\r\n  border-color: var(--text-muted);\r\n}\r\n\r\n.server-option.selected {\r\n  border-color: var(--accent);\r\n  background: rgba(0, 255, 136, 0.05);\r\n}\r\n\r\n.server-info {\r\n  flex: 1;\r\n}\r\n\r\n.server-name {\r\n  font-weight: 500;\r\n  font-size: 0.875rem;\r\n}\r\n\r\n.server-url {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n/* Alert */\r\n.alert {\r\n  padding: 1rem 1.5rem;\r\n  border-radius: 4px;\r\n  margin-bottom: 1.5rem;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 1rem;\r\n  animation: fadeIn 0.3s ease;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.875rem;\r\n}\r\n\r\n.alert-success {\r\n  background: rgba(0, 255, 136, 0.1);\r\n  border: 1px solid var(--success);\r\n  color: var(--success);\r\n}\r\n.alert-error {\r\n  background: rgba(239, 68, 68, 0.1);\r\n  border: 1px solid var(--danger);\r\n  color: var(--danger);\r\n}\r\n.alert-warning {\r\n  background: rgba(245, 158, 11, 0.1);\r\n  border: 1px solid var(--warning);\r\n  color: var(--warning);\r\n}\r\n\r\n.alert-close {\r\n  margin-left: auto;\r\n  background: none;\r\n  border: none;\r\n  color: currentColor;\r\n  opacity: 0.7;\r\n  cursor: pointer;\r\n}\r\n\r\n/* Confirm */\r\n.confirm-body {\r\n  padding: 1.5rem;\r\n  display: flex;\r\n  gap: 1rem;\r\n}\r\n\r\n.confirm-icon {\r\n  font-size: 1.5rem;\r\n  color: var(--warning);\r\n}\r\n\r\n.confirm-message {\r\n  margin: 0;\r\n  line-height: 1.5;\r\n}\r\n\r\n.confirm-actions {\r\n  padding: 1rem 1.5rem;\r\n  background: var(--bg-panel);\r\n  display: flex;\r\n  justify-content: flex-end;\r\n  gap: 1rem;\r\n  border-top: 1px solid var(--border);\r\n}\r\n\r\n/* Footer */\r\n.footer {\r\n  text-align: center;\r\n  padding: 3rem 0;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n  color: var(--text-muted);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.2em;\r\n  opacity: 0.5;\r\n}\r\n\r\n/* Scrollbar */\r\n::-webkit-scrollbar {\r\n  width: 8px;\r\n}\r\n\r\n::-webkit-scrollbar-track {\r\n  background: var(--bg-void);\r\n}\r\n\r\n::-webkit-scrollbar-thumb {\r\n  background: var(--border);\r\n  border-radius: 4px;\r\n}\r\n\r\n::-webkit-scrollbar-thumb:hover {\r\n  background: var(--text-muted);\r\n}\r\n\r\n.empty-state {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 6rem 0;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.empty-state-icon {\r\n  font-size: 3rem;\r\n  margin-bottom: 1rem;\r\n  opacity: 0.5;\r\n}\r\n\r\n.empty-state-text {\r\n  font-family: var(--font-mono);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.1em;\r\n}\r\n\r\n.loading {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  width: 100%;\r\n  height: 100%;\r\n  background: var(--bg-void);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  z-index: 2000;\r\n}\r\n\r\n.spinner {\r\n  width: 40px;\r\n  height: 40px;\r\n  border: 2px solid var(--border);\r\n  border-top-color: var(--accent);\r\n  border-radius: 50%;\r\n  animation: spin 1s linear infinite;\r\n}\r\n\r\n@keyframes spin {\r\n  to {\r\n    transform: rotate(360deg);\r\n  }\r\n}\r\n\r\n/* Health */\r\n.health-page {\r\n  padding-top: 1.5rem;\r\n  padding-bottom: 3rem;\r\n}\r\n\r\n.health-toolbar {\r\n  gap: 1rem;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.health-card {\r\n  padding-left: 1.75rem;\r\n  padding-right: 1.75rem;\r\n}\r\n\r\n.health-card:hover {\r\n  border-color: var(--border);\r\n  transform: none;\r\n}\r\n\r\n.health-card::before {\r\n  background: linear-gradient(180deg, var(--accent), rgba(0, 255, 136, 0.12));\r\n}\r\n\r\n.health-status-row {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-start;\r\n  gap: 1rem;\r\n  margin-bottom: 1.25rem;\r\n  padding-left: 1rem;\r\n}\r\n\r\n.health-table-wrap {\r\n  overflow-x: auto;\r\n  margin-left: 1rem;\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  background: var(--bg-panel);\r\n}\r\n\r\n.health-table {\r\n  width: 100%;\r\n  table-layout: fixed;\r\n  border-collapse: collapse;\r\n  min-width: 880px;\r\n}\r\n\r\n.health-table th,\r\n.health-table td {\r\n  padding: 0.55rem 0.6rem;\r\n  text-align: right;\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.04);\r\n  vertical-align: middle;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.health-table th:nth-child(1),\r\n.health-table th:nth-child(2),\r\n.health-table td:nth-child(1),\r\n.health-table td:nth-child(2) {\r\n  text-align: center;\r\n}\r\n\r\n.health-table th {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.6875rem;\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n  color: var(--text-muted);\r\n  background: rgba(255, 255, 255, 0.02);\r\n  position: sticky;\r\n  top: 0;\r\n}\r\n\r\n.health-table tbody tr:hover {\r\n  background: rgba(255, 255, 255, 0.02);\r\n}\r\n\r\n.health-table tbody tr:last-child td {\r\n  border-bottom: none;\r\n}\r\n\r\n.health-mono {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.72rem;\r\n}\r\n\r\n.health-table td.health-badge-cell {\r\n  overflow: visible;\r\n  text-overflow: clip;\r\n}\r\n\r\n.health-col-target {\r\n  width: 8.5%;\r\n}\r\n\r\n.health-col-proto {\r\n  width: 4.5%;\r\n}\r\n\r\n.health-col-health {\r\n  width: 6%;\r\n}\r\n\r\n.health-col-peer {\r\n  width: 16%;\r\n}\r\n\r\n.health-col-rate {\r\n  width: 7%;\r\n}\r\n\r\n.health-col-bytes {\r\n  width: 11%;\r\n}\r\n\r\n.health-col-rtt {\r\n  width: 8%;\r\n}\r\n\r\n.health-col-queue {\r\n  width: 6%;\r\n}\r\n\r\n.health-col-retrans {\r\n  width: 10%;\r\n}\r\n\r\n.health-empty {\r\n  text-align: center;\r\n  color: var(--text-muted);\r\n  font-family: var(--font-mono);\r\n  letter-spacing: 0.04em;\r\n}\r\n\r\n.health-hidden {\r\n  display: none;\r\n}\r\n\r\n.target-pill,\r\n.health-pill,\r\n.proto-pill {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 0.25rem 0.45rem;\r\n  border-radius: 999px;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.68rem;\r\n  letter-spacing: 0.04em;\r\n  border: 1px solid transparent;\r\n}\r\n\r\n.target-pill {\r\n  min-width: 5rem;\r\n}\r\n\r\n.health-pill {\r\n  min-width: 3rem;\r\n}\r\n\r\n.proto-pill {\r\n  min-width: 3.2rem;\r\n}\r\n\r\n.target-inbound {\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border-color: rgba(255, 255, 255, 0.08);\r\n  color: var(--text-main);\r\n}\r\n\r\n.target-twitch {\r\n  background: rgba(145, 70, 255, 0.14);\r\n  border-color: rgba(145, 70, 255, 0.28);\r\n  color: #d6bcff;\r\n}\r\n\r\n.target-vk {\r\n  background: rgba(0, 119, 255, 0.14);\r\n  border-color: rgba(0, 119, 255, 0.28);\r\n  color: #9ec5ff;\r\n}\r\n\r\n.target-youtube {\r\n  background: rgba(255, 0, 0, 0.14);\r\n  border-color: rgba(255, 0, 0, 0.28);\r\n  color: #ffb3b3;\r\n}\r\n\r\n.target-unknown {\r\n  background: rgba(245, 158, 11, 0.14);\r\n  border-color: rgba(245, 158, 11, 0.28);\r\n  color: #fcd34d;\r\n}\r\n\r\n.target-outbound {\r\n  background: rgba(34, 197, 94, 0.14);\r\n  border-color: rgba(34, 197, 94, 0.28);\r\n  color: #9ef0b8;\r\n}\r\n\r\n.proto-srt {\r\n  background: rgba(20, 184, 166, 0.14);\r\n  border-color: rgba(20, 184, 166, 0.28);\r\n  color: #5eead4;\r\n}\r\n\r\n.proto-srtla {\r\n  background: rgba(245, 158, 11, 0.14);\r\n  border-color: rgba(245, 158, 11, 0.28);\r\n  color: #fcd34d;\r\n}\r\n\r\n.proto-rtmp {\r\n  background: rgba(99, 102, 241, 0.14);\r\n  border-color: rgba(99, 102, 241, 0.28);\r\n  color: #a5b4fc;\r\n}\r\n\r\n.proto-rtmps {\r\n  background: rgba(236, 72, 153, 0.14);\r\n  border-color: rgba(236, 72, 153, 0.28);\r\n  color: #f9a8d4;\r\n}\r\n\r\n.health-good {\r\n  background: rgba(0, 255, 136, 0.12);\r\n  border-color: rgba(0, 255, 136, 0.28);\r\n  color: var(--accent);\r\n}\r\n\r\n.health-warn {\r\n  background: rgba(245, 158, 11, 0.12);\r\n  border-color: rgba(245, 158, 11, 0.28);\r\n  color: #fbbf24;\r\n}\r\n\r\n.health-bad {\r\n  background: rgba(239, 68, 68, 0.12);\r\n  border-color: rgba(239, 68, 68, 0.28);\r\n  color: #f87171;\r\n}\r\n\r\n.text-good {\r\n  color: var(--accent) !important;\r\n}\r\n.text-warn {\r\n  color: #fbbf24 !important;\r\n}\r\n.text-bad {\r\n  color: #f87171 !important;\r\n}\r\n\r\n.stream-card {\r\n  margin-bottom: 1.5rem;\r\n}\r\n\r\n.stream-card + .stream-card {\r\n  animation-delay: 0.1s;\r\n}\r\n\r\n.stream-tracks {\r\n  font-family: var(--font-mono);\r\n  font-size: 0.7rem;\r\n  color: var(--text-muted);\r\n  opacity: 0.9;\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n/* Event Log */\r\n.event-log-card {\r\n  padding: 1.5rem 1rem;\r\n}\r\n\r\n.event-log-card:hover {\r\n  border-color: var(--border);\r\n  transform: none;\r\n}\r\n\r\n.event-log-container {\r\n  max-height: 350px;\r\n  overflow-y: auto;\r\n  background: var(--bg-void);\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  margin: 0 1rem;\r\n}\r\n\r\n.event-log-entry {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 1rem;\r\n  padding: 0.15rem 1rem;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.75rem;\r\n}\r\n\r\n.event-log-entry:hover {\r\n  background: rgba(255, 255, 255, 0.02);\r\n}\r\n\r\n.event-log-timestamp {\r\n  color: var(--text-muted);\r\n  width: 125px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.event-log-type {\r\n  font-weight: 600;\r\n  width: 210px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.event-log-stream {\r\n  color: var(--text-muted);\r\n  width: 200px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.event-log-detail {\r\n  flex-grow: 1;\r\n  color: var(--text-main);\r\n  word-break: break-all;\r\n}\r\n\r\n.event-type-connected {\r\n  color: var(--accent);\r\n}\r\n\r\n.event-type-disconnected {\r\n  color: var(--danger);\r\n}\r\n\r\n.event-type-degraded {\r\n  color: var(--warning);\r\n}\r\n\r\n/* uPlot Base & Bandwidth Chart */\r\n.uplot, .uplot *, .uplot *::before, .uplot *::after {\r\n  box-sizing: border-box;\r\n}\r\n\r\n.uplot {\r\n  font-family: var(--font-mono);\r\n  line-height: 1.5;\r\n  width: 100%;\r\n  position: relative;\r\n  user-select: none;\r\n}\r\n\r\n.u-wrap {\r\n  position: relative;\r\n  user-select: none;\r\n}\r\n\r\n.u-over, .u-under {\r\n  position: absolute;\r\n}\r\n\r\n.u-under {\r\n  overflow: hidden;\r\n}\r\n\r\n.uplot canvas {\r\n  display: block;\r\n  position: relative;\r\n  width: 100%;\r\n  height: 100%;\r\n}\r\n\r\n.u-axis {\r\n  position: absolute;\r\n}\r\n\r\n.u-select {\r\n  background: rgba(0, 255, 136, 0.12);\r\n  border-left: 1px solid var(--accent);\r\n  border-right: 1px solid var(--accent);\r\n  position: absolute;\r\n  pointer-events: none;\r\n}\r\n\r\n.u-cursor-x, .u-cursor-y {\r\n  position: absolute;\r\n  left: 0;\r\n  top: 0;\r\n  pointer-events: none;\r\n  will-change: transform;\r\n}\r\n\r\n.u-hz .u-cursor-x, .u-vt .u-cursor-y {\r\n  height: 100%;\r\n  border-right: 1px dashed rgba(255, 255, 255, 0.2);\r\n}\r\n\r\n.u-hz .u-cursor-y, .u-vt .u-cursor-x {\r\n  width: 100%;\r\n  border-bottom: 1px dashed rgba(255, 255, 255, 0.15);\r\n}\r\n\r\n.u-cursor-pt {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  border-radius: 50%;\r\n  border: 0 solid;\r\n  pointer-events: none;\r\n  will-change: transform;\r\n  background-clip: padding-box !important;\r\n}\r\n\r\n.u-axis.u-off, .u-select.u-off, .u-cursor-x.u-off, .u-cursor-y.u-off, .u-cursor-pt.u-off {\r\n  display: none;\r\n}\r\n\r\n.stream-chart-card {\r\n  margin-left: 1rem;\r\n  margin-top: 0.75rem;\r\n  padding: 0.75rem;\r\n  background: var(--bg-panel);\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  position: relative;\r\n}\r\n\r\n.stream-chart-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 0.5rem;\r\n  flex-wrap: wrap;\r\n  gap: 0.5rem;\r\n}\r\n\r\n.stream-chart-legend {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.75rem;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.stream-chart-legend-item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.35rem;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.72rem;\r\n  color: var(--text-muted);\r\n}\r\n\r\n.stream-chart-legend-dot {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 50%;\r\n  display: inline-block;\r\n}\r\n\r\n.stream-chart-legend-label {\r\n  color: var(--text-main);\r\n  opacity: 0.85;\r\n}\r\n\r\n.stream-chart-controls {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.5rem;\r\n}\r\n\r\n.chart-btn-group {\r\n  display: inline-flex;\r\n  border: 1px solid var(--border);\r\n  border-radius: 4px;\r\n  overflow: hidden;\r\n  background: var(--bg-void);\r\n}\r\n\r\n.chart-btn {\r\n  background: transparent;\r\n  border: none;\r\n  color: var(--text-muted);\r\n  font-family: var(--font-mono);\r\n  font-size: 0.68rem;\r\n  padding: 0.2rem 0.5rem;\r\n  cursor: pointer;\r\n  transition: all 0.15s;\r\n}\r\n\r\n.chart-btn:hover {\r\n  color: var(--text-main);\r\n  background: rgba(255, 255, 255, 0.05);\r\n}\r\n\r\n.chart-btn.active {\r\n  background: var(--accent);\r\n  color: var(--accent-text);\r\n  font-weight: 600;\r\n}\r\n\r\n.chart-live-btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 0.35rem;\r\n  padding: 0.2rem 0.6rem;\r\n  border-radius: 4px;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.68rem;\r\n  font-weight: 600;\r\n  border: 1px solid transparent;\r\n  cursor: pointer;\r\n  transition: all 0.15s;\r\n}\r\n\r\n.chart-live-btn.live-active {\r\n  background: rgba(0, 255, 136, 0.12);\r\n  border-color: rgba(0, 255, 136, 0.3);\r\n  color: var(--accent);\r\n}\r\n\r\n.chart-live-btn.live-paused {\r\n  background: rgba(245, 158, 11, 0.12);\r\n  border-color: rgba(245, 158, 11, 0.3);\r\n  color: var(--warning);\r\n}\r\n\r\n.chart-live-dot {\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  background: currentColor;\r\n}\r\n\r\n.chart-live-btn.live-active .chart-live-dot {\r\n  animation: pulse 2s infinite;\r\n}\r\n\r\n.stream-chart-plot-wrap {\r\n  position: relative;\r\n  width: 100%;\r\n  min-height: 180px;\r\n}\r\n\r\n.uplot-wrapper {\r\n  width: 100%;\r\n  height: 180px;\r\n}\r\n\r\n.chart-tooltip {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  pointer-events: none;\r\n  z-index: 10;\r\n  background: rgba(18, 18, 20, 0.94);\r\n  backdrop-filter: blur(8px);\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  padding: 0.5rem 0.75rem;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.72rem;\r\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6);\r\n  will-change: transform;\r\n  min-width: 150px;\r\n}\r\n\r\n.chart-tooltip-time {\r\n  color: var(--text-muted);\r\n  font-size: 0.68rem;\r\n  margin-bottom: 0.35rem;\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\r\n  padding-bottom: 0.2rem;\r\n}\r\n\r\n.chart-tooltip-row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.4rem;\r\n  margin-top: 0.2rem;\r\n  white-space: nowrap;\r\n}\r\n\r\n.chart-tooltip-dot {\r\n  width: 6px;\r\n  height: 6px;\r\n  border-radius: 50%;\r\n  display: inline-block;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.chart-tooltip-name {\r\n  color: var(--text-muted);\r\n  flex: 1;\r\n}\r\n\r\n.chart-tooltip-val {\r\n  color: var(--text-main);\r\n  font-weight: 600;\r\n  text-align: right;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 640px) {\r\n  .header-actions span {\r\n    display: none;\r\n  }\r\n  .card-header {\r\n    flex-direction: column;\r\n    gap: 1rem;\r\n  }\r\n  .card-actions {\r\n    width: 100%;\r\n    justify-content: flex-end;\r\n  }\r\n  .rtmp-link {\r\n    flex-direction: column;\r\n    align-items: stretch;\r\n    gap: 0.5rem;\r\n  }\r\n  .rtmp-link-url {\r\n    word-break: break-all;\r\n  }\r\n  .health-status-row {\r\n    flex-direction: column;\r\n  }\r\n  .health-card {\r\n    padding-left: 1rem;\r\n    padding-right: 1rem;\r\n  }\r\n  .health-table-wrap {\r\n    margin-left: 0;\r\n  }\r\n  .stream-chart-card {\r\n    margin-left: 0;\r\n  }\r\n  .stream-chart-header {\r\n    flex-direction: column;\r\n    align-items: flex-start;\r\n  }\r\n}\r\n\r\n";
